import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"为什么选择曦寒","description":"","frontmatter":{},"headers":[],"relativePath":"why.md","filePath":"why.md","lastUpdated":1793828433000}`),a={name:`why.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="为什么选择曦寒" tabindex="-1">为什么选择曦寒 <a class="header-anchor" href="#为什么选择曦寒" aria-label="Permalink to “为什么选择曦寒”">​</a></h1><p>本页是选型说明：XiHan Framework 适合什么项目、换来什么、付出什么，以及在当前预览阶段的限制。适合正在评估后端框架的团队阅读。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>建议</th></tr></thead><tbody><tr><td>中大型、长期维护、多人协作的 .NET 后端，重视依赖边界与可替换性</td><td>适合</td></tr><tr><td>多租户 SaaS、企业中后台，需要租户、权限、审计、工作流、调度这类通用能力</td><td>适合</td></tr><tr><td>同一业务要同时提供 REST、gRPC、MCP tool 或命令行</td><td>适合</td></tr><tr><td>需要第三方用其他语言写插件，或要求插件崩溃不拖垮宿主</td><td>适合</td></tr><tr><td>目标是 Native AOT 发布或冷启动敏感的服务</td><td>适合，非 AOT 的 Provider 需替换或接受 JIT</td></tr><tr><td>短期项目，只要几个 CRUD 接口</td><td>直接用 ASP.NET Core 最小 API 更省事</td></tr><tr><td>必须马上上生产、需要 nuget.org 上的正式版</td><td>框架仍是预览，见下文「当前限制」</td></tr></tbody></table><h2 id="它解决的问题" tabindex="-1">它解决的问题 <a class="header-anchor" href="#它解决的问题" aria-label="Permalink to “它解决的问题”">​</a></h2><h3 id="装配可检查" tabindex="-1">装配可检查 <a class="header-anchor" href="#装配可检查" aria-label="Permalink to “装配可检查”">​</a></h3><p>多数模块化框架把依赖写在特性或基类上，依赖关系要到运行时才知道。这里每个特性带一份清单，按能力 ID 声明依赖：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>xihan.persistence.inmemory &lt;版本&gt; (default)</span></span>
<span class="line"><span>  provides persistence.relational@1</span></span>
<span class="line"><span>  requires kernel.hosting@1 -&gt; xihan.kernel.core</span></span></code></pre></div><p>内核在构建期求解全部清单，缺失依赖、循环、版本冲突、同一能力多个候选都会带着双方信息报错；启动日志与 <code>graph</code> 命令打印同一份已解析图。同一能力有多个 Provider 时，选择写在配置 <code>XiHan:Providers:&lt;能力 ID&gt;</code> 里，不靠注册顺序。</p><h3 id="横切逻辑有固定位置" tabindex="-1">横切逻辑有固定位置 <a class="header-anchor" href="#横切逻辑有固定位置" aria-label="Permalink to “横切逻辑有固定位置”">​</a></h3><p>认证、租户、授权、校验、幂等、事务分别落在管道的固定阶段，任何协议进来的调用都经过同一条管道。中间件只关心自己的阶段，顺序由「阶段 → 约束 → 归属」确定并可打印，不依赖动态代理。</p><h3 id="一份契约-多种协议" tabindex="-1">一份契约，多种协议 <a class="header-anchor" href="#一份契约-多种协议" aria-label="Permalink to “一份契约，多种协议”">​</a></h3><p>操作以 <code>[Operation]</code> 声明一次，源生成器产出 JSON Schema。HTTP 路由、OpenAPI 文档、gRPC 的 <code>.proto</code>、MCP 的 tool 描述、命令行参数都由同一份契约推出，授权要求与错误码在各协议上一致。</p><h3 id="默认实现与-provider-分离" tabindex="-1">默认实现与 Provider 分离 <a class="header-anchor" href="#默认实现与-provider-分离" aria-label="Permalink to “默认实现与 Provider 分离”">​</a></h3><p>每个子系统的抽象都有一个零外部依赖、容量有界的默认实现，开发与测试不需要数据库、Redis 或消息代理。上线时加 Provider 包与一行 <code>UseFeature</code>，默认实现自动让位；Provider 与默认实现通过同一套一致性套件，行为差异在套件里可见。</p><h3 id="边界由机器执行" tabindex="-1">边界由机器执行 <a class="header-anchor" href="#边界由机器执行" aria-label="Permalink to “边界由机器执行”">​</a></h3><p>依赖方向、包 ID 文法、命名空间、零反射、第三方类型泄漏、XML 文档、消息键与语言文件的一致性都由架构测试与分析器执行，不靠代码评审记忆。</p><h2 id="换来的代价" tabindex="-1">换来的代价 <a class="header-anchor" href="#换来的代价" aria-label="Permalink to “换来的代价”">​</a></h2><table tabindex="0"><thead><tr><th>代价</th><th>说明</th></tr></thead><tbody><tr><td>写法更显式</td><td>每个特性要写清单；服务、权限、操作、消息处理器都要在 <code>Configure</code> 里显式登记，源生成器的登记也要显式调用</td></tr><tr><td>序列化要源生成</td><td>操作的请求与响应、领域事件的载荷要登记到 <code>JsonSerializerContext</code>；操作的类型没有登记时生成器报 <code>XHG002</code></td></tr><tr><td>失败用 <code>Result</code> 表达</td><td>仓储、缓存、消息等端口返回 <code>Result</code> 而不是抛异常，调用方要处理失败分支</td></tr><tr><td>文案不写在代码里</td><td>面向人的文字以消息键引用，每个键要在 10 个语言文件里各有一行</td></tr><tr><td>概念更多</td><td>能力 ID、清单、管道阶段、操作契约、协议适配器是新概念，团队需要时间统一认识</td></tr></tbody></table><h2 id="当前限制" tabindex="-1">当前限制 <a class="header-anchor" href="#当前限制" aria-label="Permalink to “当前限制”">​</a></h2><ul><li>当前只有预览版，安装要带 <code>--prerelease</code>，见<a href="./quickstart#获取预览包">快速上手</a>。</li><li>公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整。</li><li>框架不提供机器人、消息通知渠道、模板引擎、脚本引擎、搜索引擎、HTTP 客户端封装、网关、SignalR 封装、对象映射，替代做法见<a href="./guide/faq#框架不提供哪些能力">常见问题</a>。</li><li>Provider 覆盖面以<a href="./packages/">包总览</a>列出的为准：持久化有 EF Core 与 SqlSugar，没有 MongoDB；远程配置有 Nacos，没有 Apollo 与 Vault；对象存储有文件系统与 S3 兼容服务。</li></ul><h2 id="用最小成本验证" tabindex="-1">用最小成本验证 <a class="header-anchor" href="#用最小成本验证" aria-label="Permalink to “用最小成本验证”">​</a></h2><ol><li>按<a href="./quickstart">快速上手</a>写一个操作，确认装配、管道与 Problem Details 的行为。</li><li>运行仓库里的 <code>framework/samples/SimpleApp</code>：同一份订单契约同时在 HTTP、gRPC、MCP 上服务，入站 CloudEvents 经管道交给消息处理器，带租户、ApiKey 认证、权限、事务与发件箱，零外部设施。</li><li>把其中一个默认实现换成团队要用的 Provider（如 <code>Persistence.EntityFrameworkCore</code> 或 <code>Caching.Redis</code>），确认业务代码不需要改。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./introduction">框架简介</a></li><li><a href="./overview">框架概述</a></li><li><a href="./quickstart">快速上手</a></li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};